<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">#define</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TASK_BLOCKED</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  2</span></span>
